mapper.select:
/* QA선정 관리 (7060) */
/* AdminQaTargetMapper.selectList */
/* QA 대상선정 설정정보 목록 */
SELECT
	A.QLAS_SLT_MNG_ID, A.AI_INPT_IMEX_DSCD, A.QLAS_ITM_TOT_CNT, A.QLAS_VOLN_CHC_CNT, 
	A.QLAS_SLBS_VLD_YN, A.AI_INPT_LIST_ID, A.INPT_SANCTION_NO, A.QLAS_SLT_RGS_DTM, 
	A.QLAS_SLT_END_DTM, A.TRN_LOG_SRNO, A.LST_DB_CHG_ID, A.LST_DB_CHG_DTM
FROM CSPD107TI A
WHERE A.QLAS_SLBS_VLD_YN = 'Y'

/* QA선정 관리 (7060) */
/* AdminQaTargetMapper.selectQaExTarget */
SELECT	A.QLAS_SLT_MNG_ID, A.AI_INPT_IMEX_DSCD, A.QLAS_ITM_TOT_CNT, A.QLAS_VOLN_CHC_CNT, 
		A.QLAS_SLBS_VLD_YN, A.AI_INPT_LIST_ID, A.INPT_SANCTION_NO, A.QLAS_SLT_RGS_DTM, 
		A.QLAS_SLT_END_DTM, A.TRN_LOG_SRNO, A.LST_DB_CHG_ID, A.LST_DB_CHG_DTM
FROM CSPD107TI A
WHERE A.AI_INPT_IMEX_DSCD = #{aiInptImexDscd}
